components.css:
.ds-media-card { position: relative; width: 176px; aspect-ratio: 2/3; padding: 8px; transition: transform 0.3s cubic-bezier(0.4,0,0.2,1); }
.ds-media-card:hover { transform: scale(1.05); }
.ds-media-link { position: relative; display: block; width: 100%; height: 100%; overflow: hidden; border-radius: 16px; background: var(--color-dark-surface-2); box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1); transition: box-shadow 0.3s; }
.ds-media-card:hover .ds-media-link { box-shadow: 0 25px 50px -12px rgb(0 0 0 / 0.25); }
.ds-media-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.ds-media-link img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ds-media-scrim { position: absolute; inset: auto 0 0 0; display: flex; align-items: flex-end; justify-content: space-between; gap: 8px; padding: 40px 10px 10px; background: linear-gradient(to top, rgb(0 0 0 / 0.85), rgb(0 0 0 / 0.45), transparent); transition: padding 0.3s; }
.ds-media-card:hover .ds-media-scrim { padding-top: 64px; }
.ds-media-title { color: #fff; font: 600 0.875rem/1.35 Inter, sans-serif; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ds-media-rating { display: inline-flex; align-items: center; gap: 2px; flex-shrink: 0; color: var(--color-dark-accent); font: 600 0.75rem Inter, sans-serif; font-variant-numeric: tabular-nums; }
.ds-save-btn { position: absolute; top: 14px; right: 14px; width: 40px; height: 40px; display: inline-flex; align-items: center; justify-content: center; border: none; border-radius: 9999px; background: rgb(0 0 0 / 0.45); backdrop-filter: blur(4px); color: #fff; cursor: pointer; opacity: 0; transition: opacity 0.2s, background-color 0.2s; }
.ds-media-card:hover .ds-save-btn, .ds-media-card:focus-within .ds-save-btn { opacity: 1; }
.ds-save-btn:hover { background: var(--color-accent); }
.ds-save-btn:focus-visible { opacity: 1; outline: 2px solid var(--color-accent); outline-offset: 2px; }
.ds-save-btn[aria-pressed="true"] { opacity: 1; background: var(--color-accent); }
@media (hover: none) { .ds-save-btn { opacity: 1; } }

.ds-lead { position: relative; isolation: isolate; display: grid; overflow: hidden; border-radius: 20px; background: var(--color-dark-surface-1); box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1); transition: box-shadow 0.3s; min-height: 420px; }
.ds-lead:hover, .ds-lead:focus-within { box-shadow: 0 25px 50px -12px rgb(0 0 0 / 0.25); }
.ds-lead-img { grid-area: 1/1; width: 100%; height: 100%; object-fit: cover; object-position: top; transition: transform 0.7s ease-out; }
.ds-lead:hover .ds-lead-img { transform: scale(1.02); }
.ds-lead-shade { position: absolute; inset: 0; background: linear-gradient(to right, rgb(0 0 0 / 0.85), rgb(0 0 0 / 0.45), transparent); }
.ds-lead-body { grid-area: 1/1; z-index: 1; align-self: end; max-width: 48rem; padding: 32px 32px 48px; }
.ds-lead-title { margin: 0; color: #fff; font: 700 3rem/1.05 Inter, sans-serif; letter-spacing: -0.025em; text-wrap: balance; }
.ds-lead-title a { color: inherit; text-decoration: none; outline: none; }
.ds-lead-title a::after { content: ""; position: absolute; inset: 0; border-radius: 20px; }
.ds-lead-title a:focus-visible::after { outline: 2px solid var(--color-dark-accent); outline-offset: -4px; }
.ds-lead-meta { display: flex; flex-wrap: wrap; gap: 4px 12px; margin: 12px 0 0; color: rgb(255 255 255 / 0.8); font: 400 1rem Inter, sans-serif; }
.ds-lead-rating { display: inline-flex; align-items: center; gap: 4px; color: var(--color-dark-accent); font-weight: 600; font-variant-numeric: tabular-nums; }
.ds-lead-overview { max-width: 62ch; margin: 12px 0 0; color: rgb(255 255 255 / 0.85); font: 400 1rem/1.625 Inter, sans-serif; }
.ds-lead-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 20px; }
.ds-lead-cta { display: inline-flex; align-items: center; padding: 10px 20px; border-radius: 9999px; background: var(--color-dark-accent); color: var(--color-dark-bg-main); font: 600 0.875rem Inter, sans-serif; transition: background-color 0.2s; }
.ds-lead:hover .ds-lead-cta { background: color-mix(in srgb, var(--color-dark-accent) 88%, white); }
.ds-lead-save { position: relative; z-index: 10; display: inline-flex; align-items: center; gap: 8px; padding: 10px 20px; border: none; border-radius: 9999px; background: rgb(255 255 255 / 0.15); backdrop-filter: blur(4px); color: #fff; font: 600 0.875rem Inter, sans-serif; cursor: pointer; transition: background-color 0.2s; }
.ds-lead-save:hover { background: rgb(255 255 255 / 0.25); }
.ds-lead-save:focus-visible { outline: 2px solid var(--color-dark-accent); outline-offset: 2px; }
.ds-lead-save[aria-pressed="true"] { background: #fff; color: var(--color-dark-bg-main); }

.ds-ranked { list-style: none; margin: 0; padding: 0; max-width: 360px; }
.ds-ranked-row { display: flex; align-items: center; gap: 12px; padding: 8px 12px 8px 8px; border-radius: 12px; background: var(--color-surface-3); box-shadow: 0 1px 2px rgb(0 0 0 / 0.05); text-decoration: none; transition: background-color 0.2s, box-shadow 0.2s; }
.ds-ranked-row:hover { background: var(--color-surface-2); box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1); }
.ds-ranked-row:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.ds-rank { width: 36px; flex-shrink: 0; text-align: center; color: var(--color-secondary); font: 700 1.875rem/1 Inter, sans-serif; letter-spacing: -0.025em; font-variant-numeric: tabular-nums; }
.ds-thumb { width: 44px; height: 64px; flex-shrink: 0; border-radius: 6px; object-fit: cover; background: var(--color-dark-surface-3); }
.ds-ranked-text { min-width: 0; flex: 1; }
.ds-ranked-title { display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--color-text-high); font: 600 1rem Inter, sans-serif; }
.ds-ranked-meta { display: flex; align-items: center; gap: 8px; margin-top: 2px; color: var(--color-text-low); font: 400 0.75rem Inter, sans-serif; font-variant-numeric: tabular-nums; }
.ds-ranked-rating { display: inline-flex; align-items: center; gap: 2px; color: var(--color-accent-ink); font-weight: 600; }

.ds-search { display: flex; align-items: center; gap: 8px; max-width: 48rem; padding: 8px 8px 8px 24px; border-radius: 9999px; background: var(--color-surface-3); box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1); transition: box-shadow 0.2s; }
.ds-search:focus-within { box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1), 0 0 0 2px var(--color-accent); }
.ds-search-input { flex: 1; min-width: 0; padding: 8px 0; border: none; background: transparent; outline: none; color: var(--color-text-high); caret-color: var(--color-accent); font: 400 1rem Inter, sans-serif; }
.ds-search-input::placeholder { color: var(--color-text-low); }
.ds-search-btn { width: 40px; height: 40px; flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center; border: none; border-radius: 9999px; background: transparent; color: var(--color-text-low); cursor: pointer; transition: background-color 0.2s, color 0.2s; }
.ds-search-btn:hover { background: var(--color-accent-ink); color: #fff; }
.ds-search-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.ds-btn-primary { display: inline-flex; align-items: center; gap: 8px; padding: 8px 16px; border: none; border-radius: 9999px; background: var(--color-accent); color: #fff; font: 500 0.875rem Inter, sans-serif; cursor: pointer; transition: opacity 0.2s; }
.ds-btn-primary:hover { opacity: 0.9; }
.ds-btn-primary:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.ds-btn-ink { display: inline-flex; align-items: center; gap: 8px; padding: 8px 20px; border: none; border-radius: 9999px; background: var(--color-accent-ink); color: #fff; font: 600 0.875rem Inter, sans-serif; cursor: pointer; transition: background-color 0.2s; }
.ds-btn-ink:hover { background: var(--color-primary); }
.ds-btn-ink:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.ds-navbar { display: flex; align-items: center; justify-content: space-between; gap: 24px; height: 64px; padding: 0 32px; background: color-mix(in srgb, var(--color-surface-3) 80%, transparent); backdrop-filter: blur(4px); box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1); }
.ds-brand { color: var(--color-text-high); font: 700 1.5rem Inter, sans-serif; text-decoration: none; }
.ds-nav-links { display: flex; align-items: center; gap: 24px; }
.ds-nav-link { display: inline-flex; align-items: center; gap: 8px; color: var(--color-text-low); font: 500 0.875rem Inter, sans-serif; text-decoration: none; border-radius: 4px; transition: color 0.2s; }
.ds-nav-link:hover, .ds-nav-link[aria-current="page"] { color: var(--color-accent-ink); }
.ds-nav-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 4px; }
.ds-nav-search { display: flex; align-items: center; width: 320px; border-radius: 9999px; background: var(--color-surface-2); transition: box-shadow 0.2s; }
.ds-nav-search:focus-within { box-shadow: 0 0 0 2px var(--color-accent); }
.ds-nav-search input { flex: 1; min-width: 0; padding: 8px 24px; border: none; background: transparent; outline: none; color: var(--color-text-high); font: 400 0.875rem Inter, sans-serif; }
.ds-nav-search button { margin-right: 8px; padding: 8px; border: none; border-radius: 9999px; background: transparent; color: var(--color-text-low); cursor: pointer; }

.ds-bottom-nav { display: flex; justify-content: space-around; align-items: center; height: 48px; max-width: 420px; background: var(--color-surface-1); backdrop-filter: blur(4px); box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1); }
.ds-bottom-btn { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; height: 100%; min-width: 64px; padding: 0 16px; border: none; background: transparent; color: var(--color-text-low); font: 500 0.75rem Inter, sans-serif; cursor: pointer; transition: color 0.2s; }
.ds-bottom-btn[aria-expanded="true"] { color: var(--color-accent-ink); }
.ds-bottom-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: -2px; }

.ds-browse { display: grid; gap: 16px; font-family: Inter, sans-serif; }
.ds-browse-row { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
.ds-seg { display: inline-flex; padding: 4px; border-radius: 9999px; background: var(--color-surface-1); box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1); }
.ds-seg-item { display: inline-flex; align-items: center; height: 32px; padding: 0 16px; border-radius: 9999px; color: var(--color-text-low); font: 600 0.875rem Inter, sans-serif; text-decoration: none; transition: color 0.2s, background-color 0.2s; }
.ds-seg-item:hover { color: var(--color-text-high); }
.ds-seg-item[aria-current="page"] { background: var(--color-surface-3); color: var(--color-text-high); box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1); }
.ds-seg-item:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.ds-select { position: relative; display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 36px 0 16px; border-radius: 9999px; background: var(--color-surface-1); box-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1); font-size: 0.875rem; }
.ds-select:focus-within { box-shadow: 0 0 0 2px var(--color-accent); }
.ds-select span { color: var(--color-text-low); }
.ds-select select { appearance: none; border: none; background: transparent; color: var(--color-text-high); font: 600 0.875rem Inter, sans-serif; outline: none; cursor: pointer; }
.ds-select svg { position: absolute; right: 12px; color: var(--color-text-low); pointer-events: none; }
.ds-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ds-chip { display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 16px; border: none; border-radius: 9999px; background: var(--color-surface-1); color: var(--color-text-high); font: 500 0.875rem Inter, sans-serif; cursor: pointer; transition: background-color 0.2s, color 0.2s; }
.ds-chip:hover { background: var(--color-surface-3); }
.ds-chip[aria-pressed="true"] { background: var(--color-accent-ink); color: #fff; }
.ds-chip[aria-pressed="true"]:hover { background: var(--color-primary); }
.ds-chip svg { margin-left: -4px; }
.ds-chip:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.ds-empty { display: flex; flex-direction: column; align-items: center; gap: 16px; max-width: 448px; padding: 32px; border-radius: 16px; background: var(--color-surface-2); text-align: center; }
.ds-empty-icon { display: flex; align-items: center; justify-content: center; padding: 16px; border-radius: 9999px; background: var(--color-surface-3); color: var(--color-text-low); }
.ds-empty h3 { margin: 0; color: var(--color-text-high); font: 700 1.25rem/1.2 Inter, sans-serif; }
.ds-empty p { margin: 0; color: var(--color-text-low); font: 400 0.875rem/1.5 Inter, sans-serif; }
.ds-empty-cta { display: inline-flex; padding: 10px 20px; border-radius: 9999px; background: var(--color-accent-ink); color: #fff; font: 600 0.875rem Inter, sans-serif; text-decoration: none; transition: background-color 0.2s; }
.ds-empty-cta:hover { background: var(--color-primary); }
.ds-empty-cta:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
